<?php
declare(strict_types=1);
require_once __DIR__.'/_bootstrap.php';if(($_SERVER['REQUEST_METHOD']??'')!=='POST')sietelsa_abort(405);if(!csrf_is_valid((string)($_POST['csrf_token']??'')))sietelsa_abort(419);$id=max(0,(int)($_POST['id']??0));$action=(string)($_POST['action']??'');if($id<1)sietelsa_abort(422,'',new InvalidArgumentException('ID de empresa inválido.'),['module'=>'companies','action'=>$action]);
try{if($action==='activate'){$companyService->activate($id,$currentUser,$companyContextUser);flash_set('success','Empresa activa','La empresa quedó seleccionada para esta sesión.');}elseif($action==='deactivate'){$companyService->changeState($id,'inactiva',$currentUser,$companyContextUser);flash_set('success','Empresa desactivada','La empresa dejó de estar disponible para operar.');}elseif($action==='enable'){$companyService->changeState($id,'activa',$currentUser,$companyContextUser);flash_set('success','Empresa habilitada','La empresa volvió a estar disponible.');}elseif($action==='block'){$companyService->changeState($id,'bloqueada',$currentUser,$companyContextUser);flash_set('success','Empresa bloqueada','El acceso operativo a la empresa fue bloqueado.');}else throw new InvalidArgumentException('Acción de empresa no válida.');}
catch(InvalidArgumentException|DomainException $e){flash_set('error','Operación no completada',$e->getMessage());}header('Location: '.app_url('src/dashboard/companies/index.php'));exit;
